-- Day 0 of the season: 10 January, 09:00 in New York, this year.
create temp table pcb_clock as
  select (date_trunc('year', now() at time zone 'America/New_York') + interval '9 days 9 hours')
           at time zone 'America/New_York' as t0;
grant select on pcb_clock to service_role, authenticated;

create function pg_temp.pcb_day(p_day integer) returns timestamptz
language sql stable as $$ select t0 + p_day * interval '1 day' from pcb_clock $$;

create function pg_temp.pcb_seg(p_slug text) returns uuid
language sql stable as $$
  select pc.global_segment_id from park_courses pc join parks p on p.id = pc.park_id
   where p.slug = 'pocahontas' and pc.slug = p_slug
$$;

-- A run as a phone sync lands it: the row naming its track, then the upload.
create function pg_temp.pcb_land(p_run uuid, p_user uuid, p_key text, p_start timestamptz, p_public boolean)
returns void language sql as $$
  insert into runs (id, user_id, started_at, distance_m, duration_s, source, activity_type, track_url, is_public)
  values (p_run, p_user, p_start, 5000, 1800, 'app', 'run', p_user::text || '/' || p_run::text || '.json.gz', p_public);
  insert into storage.objects (bucket_id, name, version)
  values ('runs', p_user::text || '/' || p_run::text || '.json.gz', 'pcb-' || p_key);
$$;

-- What the segment-match function sends for a run whose first fix was at
-- p_start: the stored version, the bbox candidates, the matcher's efforts.
create function pg_temp.pcb_score(p_run uuid, p_key text, p_start timestamptz)
returns text language sql as $$
  select record_segment_match(
    p_run,
    (select s.track_version from segment_match_run_source(p_run) s),
    r.min_lat, r.min_lng, r.max_lat, r.max_lng,
    (select array_agg(c.id order by c.id)
       from global_segments_in_bbox(r.min_lat, r.min_lng, r.max_lat, r.max_lng, 50, 1000) c),
    coalesce((select jsonb_agg(jsonb_build_object(
        'global_segment_id', pg_temp.pcb_seg(e ->> 'slug'),
        'time_seconds', (e ->> 'time_seconds')::numeric,
        'started_at', p_start + (e ->> 'started_offset_ms')::numeric * interval '1 millisecond',
        'matched_by', e ->> 'matched_by'))
      from jsonb_array_elements(r.efforts) e), '[]'::jsonb))
  from pcb_runs r where r.key = p_key
$$;

-- The matcher's time for a run on a course, as the boards show it (whole seconds).
create function pg_temp.pcb_time(p_key text, p_slug text) returns integer
language sql stable as $$
  select round((e ->> 'time_seconds')::numeric)::integer
    from pcb_runs r, jsonb_array_elements(r.efforts) e
   where r.key = p_key and e ->> 'slug' = p_slug
$$;

