-- The matcher tests time every course by the lines the fixture derives (or
-- the manifest curates). These are the lines the database holds.
select is(
  (select count(*)::int
     from pcb_lines l
     join global_segments gs on gs.id = pg_temp.pcb_seg(l.slug)
    where abs(gs.start_gate_lat - l.start_lat) < 1e-9 and abs(gs.start_gate_lng - l.start_lng) < 1e-9
      and abs(gs.start_gate_bearing_deg - l.start_bearing_deg) < 1e-6
      and gs.start_gate_half_width_m = l.start_half_width_m and gs.start_gate_source = l.start_source
      and abs(gs.end_gate_lat - l.end_lat) < 1e-9 and abs(gs.end_gate_lng - l.end_lng) < 1e-9
      and abs(gs.end_gate_bearing_deg - l.end_bearing_deg) < 1e-6
      and gs.end_gate_half_width_m = l.end_half_width_m and gs.end_gate_source = l.end_source),
  6,
  'every course''s start and end lines in the database are the ones the matcher tests time it by');

