-- ── A closed course ──
-- A course closed by an admin or by the catalogue sync keeps its times and
-- boards (docs/features/park_courses.md § Wording and safety). Nothing in the
-- match or the write reads the course's status either, so a run on a closed
-- course is still timed and ranked. Pinned as it is; whether a closed course
-- should stop taking new times is the owner's call (issue #1342).
reset role;
set local "request.jwt.claims" = '{}';
update park_courses pc set status = 'closed', status_note = 'Closed for the test.'
  from parks p where p.id = pc.park_id and p.slug = 'pocahontas' and pc.slug = 'swift-creek-10k';
select pg_temp.pcb_land('cb000000-0000-4000-8000-00000000000a', '00000000-0000-0000-0000-0000000cb0a1', '10k_clean', pg_temp.pcb_day(6), true);
set local role service_role;
set local "request.jwt.claims" = '{"role":"service_role"}';
select is(
  pg_temp.pcb_score('cb000000-0000-4000-8000-00000000000a', '10k_clean', pg_temp.pcb_day(6)),
  'recorded', 'a run on the closed 10K is recorded');
reset role;
set local "request.jwt.claims" = '{}';
select is(
  (select array_agg(pc.slug order by pc.slug)
     from global_segment_efforts e join park_courses pc on pc.global_segment_id = e.global_segment_id
    where e.run_id = 'cb000000-0000-4000-8000-00000000000a'),
  array['swift-creek-10k'], 'and timed on it');

set local role authenticated;
set local "request.jwt.claims" = '{"sub":"00000000-0000-0000-0000-0000000cb0c3","role":"authenticated"}';
select results_eq(
  $$ select display_name, time_seconds
       from global_segment_leaderboard(pg_temp.pcb_seg('swift-creek-10k'), null, null, 10, null,
              (select park_season(p) from parks p where p.slug = 'pocahontas')) $$,
  $$ values ('Pcb Runner A'::text, pg_temp.pcb_time('10k_clean', 'swift-creek-10k')) $$,
  'the closed course''s board ranks it');
select is(
  (select r.display_name from park_course_records() r join park_courses pc on pc.id = r.course_id
    where pc.global_segment_id = pg_temp.pcb_seg('swift-creek-10k')),
  'Pcb Runner A', 'and park_course_records reports it as the closed course''s record');

select * from finish();
rollback;
